import re
import time


def force_list(parameter):
    """
    Converts non-list parameter to a single-element list
    """
    return [parameter] if not isinstance(parameter, list) else parameter


def convert_parameter_to_integer(param):
    """
    Extracts positive or negative integer from a string.
    Useful in case of SIB parameters conversion.
    :param param: String
    :return: extracted positive or negative integer from given param
    """
    found = re.search(r'(\-?\d+)', param)
    if found:
        value = int(found.group(0))
        return value
    else:
        return None


def get_timestamp_for_filesystem():
    """
    Gets current time (local) and returs formated string
    :return: YYYY.MM.DD_HH.SS as a string
    """
    year, month, mday, hour, mn, sec, wday, yday, isdst = time.localtime()
    timestamp = '{yyyy}.{mm:02}.{dd:02}_{hh:02}.{mi:02}.{ss:02}'.format(
        yyyy=year, mm=month, dd=mday, hh=hour, mi=mn, ss=sec
    )
    return timestamp


def join_string_with_timestamp_suffix(string):
    """
    Joins string given as an argument with timestamp
    :param string: string
    :return: string - underscore - timestamp as a string
    """
    if not isinstance(string, str):
        raise TypeError('Given argument is not a string')
    time_stamp = get_timestamp_for_filesystem()
    string_with_timestamp = string + '_' + time_stamp
    return string_with_timestamp
